def is_balanced(sequence: list[int]) -> bool:
    closers = {opener: closer for opener, closer in BRACKET_PAIRS}
    stack: list[int] = []
    for token in sequence:
        if token in closers:
            stack.append(closers[token])
        elif stack and token == stack[-1]:
            stack.pop()
        else:
            return False
    return not stack


def test_generate_dyck_sequence_is_balanced() -> None:
    rng = np.random.default_rng(7)
    for _ in range(20):
        sequence = generate_dyck_sequence(rng, max_depth=8, target_length=64)
        assert sequence
        assert is_balanced(sequence)


def test_generate_dyck_sequence_uses_only_bracket_tokens() -> None:
    rng = np.random.default_rng(3)
    allowed = {token for pair in BRACKET_PAIRS for token in pair}
    sequence = generate_dyck_sequence(rng, max_depth=8, target_length=128)
    assert set(sequence) <= allowed


